const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const R=path.resolve(__dirname,'..'),src=fs.readFileSync(path.join(__dirname,'readers.test.cjs'),'utf8');
const noop=n=>n==='node:test'?{test:()=>{}}:require(n),mod={exports:{}};new Function('require','__dirname','module',src)(noop,__dirname,mod);const {setup,seed,q,native,scalar}=mod.exports;
test('6900 synthetic source labels fit the unchanged 4000000-byte payload cap and validate without parsing again',async()=>{const db=await setup();try{await seed(db);await db.exec(`with template as materialized(select to_jsonb(n)t from public.newar_detail_records n limit 1),generated as(select t||jsonb_build_object('id',gen_random_uuid(),'source_id','SIZE-'||i,'order_number','SIZE-'||i,'raw',(t->'raw')||jsonb_build_object('automaticReasonLabel','1.累计提款次数0小于配置1次;2.总打码倍数'||i||'.3720(有效投注'||i||'.2/总充值100)小于配置4'))j from template cross join generate_series(1,6900)i)insert into public.newar_detail_records select(jsonb_populate_record(null::public.newar_detail_records,j)).*from generated;delete from public.newar_detail_records where source_id not like 'SIZE-%'`);const r=await scalar(db,'select private.withdraw_reason_newar_all($1,$2,$3)v',[q,{mode:'all',countries:[]},native]);assert.equal(r.noteCount,6900);assert.equal(r.summary.ruleMembership.hitCount,13800);const bytes=await scalar(db,'select octet_length($1::jsonb::text)v',[r]);assert(bytes<4000000,String(bytes));assert.equal(await scalar(db,'select private.withdraw_reason_newar_index_valid($1)v',[r]),true);await db.exec(`delete from public.newar_detail_records where substring(source_id from 6)::int>6370;with numbered as(select id,substring(source_id from 6)::int i from public.newar_detail_records),n as(select *,case when i<=2462 then 1 when i<=5478 then 2 when i<=5756 then 3 when i<=5835 then 4 when i<=5942 then 5 when i<=6054 then 6 when i<=6157 then 7 when i<=6243 then 8 when i<=6357 then 9 when i<=6368 then 10 else 11 end k from numbered),labels as(select id,array_to_string((array['总盈利'||i||'大于配置0','账户余额'||i||'大于配置0','首存金额'||i||'大于配置0','总充值'||i||'小于配置下限9','同浏览器指纹人数'||i||'大于配置5','累计提款次数'||i||'小于配置9次','提款金额'||i||'大于自动出款最大金额8','会员备注不为空,请检查备注','未完成充值,当前充值次数0','今日未通过自动出款1次,大于配置0次','同银行账户关联1次,大于配置0次'])[1:k],';')label from n)update public.newar_detail_records d set raw=d.raw||jsonb_build_object('automaticReasonLabel',l.label)from labels l where d.id=l.id`);const mixed=await scalar(db,'select private.withdraw_reason_newar_all($1,$2,$3)v',[q,{mode:'all',countries:[]},native]);assert.equal(mixed.noteCount,6370);assert.equal(mixed.summary.operatorCounts.manualWithReason,6370);const mixedBytes=await scalar(db,'select octet_length($1::jsonb::text)v',[mixed]);assert(mixedBytes<4000000,String(mixedBytes));assert.equal(await scalar(db,'select private.withdraw_reason_newar_index_valid($1)v',[mixed]),true);console.log(JSON.stringify({syntheticMixedLabels:6370,ruleHits:mixed.summary.ruleMembership.hitCount,payloadBytes:mixedBytes,cap:4000000}));await db.exec("create or replace function private.dashboard_admin_live_blocking_core(p_note text)returns jsonb language plpgsql immutable as $$begin raise exception 'parser must not run on prepared validation';end$$");assert.equal(await scalar(db,'select private.withdraw_reason_newar_index_valid($1)v',[r]),true);console.log(JSON.stringify({syntheticLabels:6900,groups:r.rows.length,payloadBytes:bytes,cap:4000000}));}finally{await db.close();}});
